115	    }
116	
117	    if (Object.hasOwn(field, 'default') && field.default !== undefined) {
118	      const fallback = field.default;
119	      if (!valueMatchesType(fallback, spec.type)) {
120	        throw new Error(`${label}: default value does not match field type ${spec.type}`);
121	      }
122	      if (!valueSatisfiesBounds(fallback, spec)) {
123	        throw new Error(`${label}: default value violates field constraints`);
124	      }
125	      spec.hasDefault = true;
126	      spec.default = fallback;
127	    }
