137	function parsePathSegments(path, label) {
138	  if (typeof path !== 'string' || path.length === 0) {
139	    throw new Error(`${label}: path must be a non-empty string`);
140	  }
141	  const segments = path.split('.');
142	  if (segments.some(part => part.length === 0)) {
143	    throw new Error(`${label}: path must not contain empty segments`);
144	  }
145	  if (segments.some(part => FORBIDDEN_SEGMENTS.has(part))) {
146	    throw new Error(`${label}: path must not contain __proto__, prototype or constructor segments`);
147	  }
148	  return segments;
149	}
