318	// A retry block is either absent (one attempt, no waiting) or present with all
319	// four parameters together, each within the same ranges the engine enforces
320	// for business action retries and compensation retries alike.
321	function compileRetry(config, label) {
322	  if (!isUsableObject(config)) {
323	    throw new Error(`${label}: retry must be an object`);
324	  }
325	  const missing = RETRY_FIELDS.filter(field => !Object.hasOwn(config, field) || config[field] === undefined);
326	  if (missing.length > 0) {
327	    throw new Error(`${label}: retry config must define all of ${RETRY_FIELDS.join(', ')} together (missing: ${missing.join(', ')})`);
328	  }
329	  if (!isIntegerIn(config.attempts, 1, 10)) {
330	    throw new Error(`${label}: retry.attempts must be an integer between 1 and 10`);
331	  }
332	  if (!isIntegerIn(config.initialDelayMs, 0, 60000)) {
333	    throw new Error(`${label}: retry.initialDelayMs must be an integer between 0 and 60000 milliseconds`);
334	  }
335	  if (!isIntegerIn(config.maxDelayMs, 0, 60000)) {
336	    throw new Error(`${label}: retry.maxDelayMs must be an integer between 0 and 60000 milliseconds`);
337	  }
338	  if (typeof config.backoffFactor !== 'number' || !Number.isFinite(config.backoffFactor)
339	    || config.backoffFactor < 1 || config.backoffFactor > 4) {
340	    throw new Error(`${label}: retry.backoffFactor must be a finite number between 1 and 4`);
341	  }
342	  if (config.maxDelayMs < config.initialDelayMs) {
343	    throw new Error(`${label}: retry.maxDelayMs must not be less than retry.initialDelayMs`);
344	  }
345	  return {
346	    attempts: config.attempts,
347	    initialDelayMs: config.initialDelayMs,
348	    backoffFactor: config.backoffFactor,
349	    maxDelayMs: config.maxDelayMs,
