1204	// the stored success value is a clone independent of any object the
1205	// implementation keeps holding. The cancellation signal applies to this
1206	// loop only — compensation runs without one.
1207	async function runBusinessAction(node, binding, implementation, context, actionAttempts, signal) {
1208	  return runWithRetries({
1209	    retry: binding.retry,
1210	    signal,
1211	    prepareArgs: attempt => [structuredClone(context.input), structuredClone(context.output), node.id, attempt],
1212	    invoke: implementation,
1213	    createRecord: attempt => ({ nodeId: node.id, attempt, ok: false, error: null, nextDelayMs: 0 }),
1214	    cloneFailureMessage: `operation "${binding.name}" returned a value that cannot be structured-cloned`,
1215	    sharedMemoryFailureMessage: `operation "${binding.name}" returned a value that contains shared memory (SharedArrayBuffer or a typed array/DataView backed by one); independent copies cannot be guaranteed, so this return value is not supported`,
