1246	// Undoes successful compensable business actions, most recent first, waiting
1247	// for each compensation to finish before starting the next. A compensation
1248	// that exhausts its retries is recorded as failed but earlier (still-pending)
1249	// actions are compensated regardless; neither the failed compensation nor the
1250	// original business operation is re-run. Compensating a node removes it from
1251	// the pending list exactly once — retried-then-succeeded actions and shared
1252	// join nodes were only recorded once to begin with.
1253	async function compensateRun(state, operations) {
1254	  const records = [];
1255	  let failed = false;
1256	  while (state.compensable.length > 0) {
1257	    const entry = state.compensable.pop();
1258	    const outcome = await runCompensation(entry, operations[entry.binding.compensation.name], records);
