1302	    state.activated.has(node.id) && !state.completed.has(node.id));
1303	  if (waiting.length === 0) return null;
1304	  return waiting.map(node => ({
1305	    nodeId: node.id,
1306	    missingDependencies: nodeDependencies.get(node)
