1471	// The cancelled terminal shape: the run stops where it is, keeps the
1472	// context, trace and attempt records produced so far, and never carries a
1473	// success result. Compensation for already-succeeded actions is attached by
1474	// withCompensation under the usual rules.
1475	function cancelledResult(state) {
1476	  return {
1477	    status: 'cancelled',
1478	    context: state.context,
1479	    trace: state.trace,
1480	    actionAttempts: state.actionAttempts,
1481	  };
1482	}
