1484	export async function executeWorkflowAsync(workflow, input = {}, operations = {}, options = undefined) {
1485	  const signal = resolveRunSignal(options);
1486	  const nodes = validateWorkflow(workflow);
1487	  verifyOperations(nodes, operations);
1488	
1489	  const state = createRunState(nodes, workflow, input);
1490	
1491	  // A signal that is already aborted stops the run before the first node —
1492	  // but only after the definition and the operation registrations above have
1493	  // been checked. Nothing executes and nothing is compensated.
1494	  if (signal && signal.aborted) {
1495	    return withCompensation(cancelledResult(state), state, operations);
1496	  }
1497	
1498	  for (;;) {
1499	    // Once the signal fires, no new regular node runs and no new business
1500	    // action attempt starts; the run ends cancelled with whatever state it
1501	    // reached, even if an end node was already visited on another branch.
1502	    if (signal && signal.aborted) {
1503	      return withCompensation(cancelledResult(state), state, operations);
1504	    }
1505	
1506	    const step = advanceSchedule(state);
1507	
1508	    if (step.kind === 'blocked') {
1509	      // Unmet dependencies end the run; successful compensable actions are
1510	      // rolled back even though an end node may already have been reached.
