1549	        }
1550	        // Capture the compensation snapshots from the state before the new
1551	        // output key lands: the action's own return value is handed to the
1552	        // compensation separately as its third argument.
1553	        const compensationSnapshot = binding.compensation === null ? null : {
1554	          input: structuredClone(state.context.input),
1555	          output: structuredClone(state.context.output),
