1566	        state.completed.add(ready.id);
1567	        continue;
1568	      }
1569	    }
1570	
1571	    const early = applyRegularNode(ready, state);
1572	    if (early) {
1573	      early.actionAttempts = state.actionAttempts;
1574	      // A failed form (invalid_input) or failed condition evaluation
1575	      // (invalid_condition) ends normal execution and triggers compensation
1576	      // of the successful business actions that ran earlier.
1577	      return withCompensation(early, state, operations);
1578	    }
1579	  }
1580	}
