node --input-type=module -e "
import { validateWorkflow, executeWorkflow, executeWorkflowAsync } from './src/engine.js';

const sab = new SharedArrayBuffer(4);
const wf = (message, extra = {}) => ({
  id: 'w', entry: 't',
  nodes: [
    { id: 't', type: 'trigger', next: 'a' },
    { id: 'a', type: 'action', message, next: 'e', ...extra },
    { id: 'e', type: 'end', result: 'done' },
  ],
});

let pass = 0, fail = 0;
const check = (name, fn) => { try { fn(); pass++; } catch (e) { fail++; console.log('FAIL:', name, '-', e.message); } };
const rejectsShared = async (message, label) => {
  check(label + ' validate', () => {
    try { validateWorkflow(wf(message)); throw new Error('no throw'); }
    catch (e) {
      if (!e.message.includes('action node a')) throw new Error('missing node id: ' + e.message);
      if (!/shared memory/.test(e.message)) throw new Error('wrong reason: ' + e.message);
    }
  });
  check(label + ' sync', () => {
    try { executeWorkflow(wf(message)); throw new Error('no throw'); }
    catch (e) { if (!/shared memory/.test(e.message)) throw e; }
  });
  await executeWorkflowAsync(wf(message)).then(
    () => { fail++; console.log('FAIL:', label, 'async accepted'); },
    e => { if (/shared memory/.test(e.message)) pass++; else { fail++; console.log('FAIL:', label, 'async:', e.message); } });
};

await rejectsShared(sab, 'bare SAB');
await rejectsShared(new Uint8Array(sab), 'typed array over SAB');
await rejectsShared(new DataView(sab), 'DataView over SAB');
await rejectsShared({ deep: [{ x: sab }] }, 'nested object/array');
await rejectsShared(new Map([[{ k: sab }, 1], [2, sab]]), 'Map key and value');
await rejectsShared(new Set([sab]), 'Set member');
await rejectsShared(Object.assign(new Error('x'), { cause: { s: sab } }), 'Error cause');
const cyc = { list: [] }; cyc.self = cyc; cyc.list.push(cyc, { s: sab });
await rejectsShared(cyc, 'cyclic graph');

// Unreachable / untaken-branch actions are checked too
check('unreachable action rejected', () => {
  const w = wf('ok');
  w.nodes.push({ id: 'orphan', type: 'action', message: sab, next: 'e' });
  try { validateWorkflow(w); throw new Error('no throw'); }
  catch (e) { if (!e.message.includes('action node orphan')) throw e; }
});

// Operation actions ignore the message entirely
check('operation action ignores shared message', () => {
  validateWorkflow(wf(sab, { operation: 'op' }));
});

// Shared memory only in dropped properties stays legal
const d = new Date(); d.extra = sab;
const re = /x/g; re.extra = sab;
const obj = {}; Object.defineProperty(obj, 'hidden', { value: sab, enumerable: false });
check('Date/RegExp/non-enumerable dropped props accepted', () => {
  validateWorkflow(wf({ d, re, obj, plain: [1, 2] }));
});

// Plain ArrayBuffer and views stay legal and independent
const ab = new ArrayBuffer(4); new Uint8Array(ab).set([1, 2, 3, 4]);
const run = executeWorkflow(wf({ buf: ab, view: new Uint8Array(ab) }));
check('plain ArrayBuffer accepted', () => {
  if (run.status !== 'completed') throw new Error(run.status);
  const saved = run.context.output.a;
  if (!(saved.buf instanceof ArrayBuffer) || saved.buf.byteLength !== 4) throw new Error('type lost');
  new Uint8Array(saved.buf)[0] = 99;
  if (new Uint8Array(ab)[0] !== 1) throw new Error('not independent');
});

// Function message error preserved
check('function message still rejected with old error', () => {
  try { validateWorkflow(wf({ f: () => {} })); throw new Error('no throw'); }
  catch (e) { if (!/structured-cloneable/.test(e.message)) throw e; }
});

// Default/undefined/null/empty-string/0/false rules unchanged
check('default and falsy messages unchanged', () => {
  const out = m => executeWorkflow(wf(m)).context.output.a;
  if (out(undefined) !== 'action:a' || out(null) !== 'action:a') throw new Error('default changed');
  if (out('') !== '' || out(0) !== 0 || out(false) !== false) throw new Error('falsy changed');
});

// Legal message snapshot stays independent of the definition
check('legal message snapshot independent', () => {
  const w = wf({ nested: { n: 1 } });
  const r = executeWorkflow(w);
  r.context.output.a.nested.n = 42;
  if (w.nodes[1].message.nested.n !== 1) throw new Error('definition mutated');
});

console.log(\`pass=\${pass} fail=\${fail}\`);
process.exit(fail ? 1 : 0);
"
